"""Verify static replay is generated by MicroRAG, never hand-written claims."""
from __future__ import annotations

import hashlib
from pathlib import Path

from scripts.micro.export_micro_v02_observatory import build_public_replay

DOCUMENTS = Path("examples/micro-v02/documents.json")


def test_all_four_decision_states_are_executed():
    data = build_public_replay(DOCUMENTS)
    assert data["schema_version"] == 1
    assert data["status"] == "FICTIONAL_STRUCTURED_CPU_SOFTWARE_REPLAY_NOT_LIVE_AI"
    assert [c["status"] for c in data["cases"]] == [
        "CONFLICT", "ANSWER", "INSUFFICIENT", "REVIEW"
    ]
    assert len(data["sources"]) == 5
    assert "fictional" in " ".join(data["limitations"]).casefold()


def test_exact_original_source_citations_and_missing_unsafe_answer():
    data = build_public_replay(DOCUMENTS)
    docs = {d["id"]: d for d in data["sources"]}
    for d in docs.values():
        assert hashlib.sha256(d["text"].encode()).hexdigest() == d["sha256"]
    for c in data["cases"]:
        assert (c["answer"] is not None) == (c["status"] == "ANSWER")
        for quote in c["citations"]:
            doc = docs[quote["doc_id"]]
            assert doc["text"][quote["start"]:quote["end"]] == quote["quote"]
            assert quote["document_sha256"] == doc["sha256"]
    conflict, answer, insufficient, review = data["cases"]
    assert {c["quote"] for c in conflict["citations"]} == {"2012", "2015"}
    assert answer["answer"] == "2019"
    assert {c["doc_id"] for c in answer["citations"]} == {
        "boreal-registry", "boreal-operations"
    }
    assert insufficient["answer"] is None and not insufficient["citations"]
    assert review["answer"] is None and not review["source_sweep_complete"]


def test_replay_is_deterministic_excluding_no_runtime_timings():
    first = build_public_replay(DOCUMENTS)
    second = build_public_replay(DOCUMENTS)
    assert first == second
    assert "timings_ms" not in first["cases"][0]
    assert all("read_calls" in item for item in first["cases"])
